import math

class LDEnacba:
    """Linearna diofantska enačba c . x = d, c je seznam koeficientov, d je desna stran.

    Če nastavimo max_x, iščemo le rešitve z vrednostmi spremenljivk 0 <= xi <= max_x (končen prostor stanj).
    """

    def __init__(self, c, d=0, max_x=None):
        self.n = len(c) # število spremenljivk diofantske enačbe
        self.c = list(c) # koefecienti linearne diofantske enačbe
        self.d = int(d) # desna stan diofantske enačbe
        self.max_x = max_x # omejitev vrednosti spremenljivk

    # izpis enačbe v razumljivi obliki
    def __str__(self):
        return " + ".join([f"{self.c[i]} * x{i+1}" for i in range(self.n)]) + f" == {self.d}"

    # izpis stanja v razumlivi obliki
    def str_s(self, s):
        return ", ".join([f"x{i+1}(*{self.c[i]}) = {s[i]}" for i in range(self.n)])

    # začetno stanje je n-terica ničel
    def zacetno(self):
        return tuple([0] * self.n)

    # končno stanje je rešitev diofantske enačbe
    def koncno(self, s):
        return self.izracunaj(s) == self.d

