class Zemljevid:

    def __init__(self, ime_csv=MATERIALI / "romania-map.csv"):
        self.ime_csv = ime_csv
        self.mesta = []
        self.poti = {}

        with open(ime_csv) as d:
            for v in d:
                (m1, m2, r) = v.split(",")

                if m1 not in self.mesta:
                    self.mesta.append(m1)
                if m2 not in self.mesta:
                    self.mesta.append(m2)

                if m1 not in self.poti:
                    self.poti[m1] = [(m2, int(r))]
                else:
                    self.poti[m1].append((m2, int(r)))

                if m2 not in self.poti:
                    self.poti[m2] = [(m1, int(r))]
                else:
                    self.poti[m2].append((m1, int(r)))


    def __repr__(self):
        return "{0}('{1}')".format(type(self).__name__, self.ime_csv)


    def sosedi(self, m):
        return self.poti[m]

    def je_mesto(self, m):
        return m in self.mesta



def sosedi_generator(zemljevid, mesto):
    """Generator sosedov mesta.
    Vrača trojice oblike (naslednje_mesto, razdalja, poteza).
    """
    for (m2, razdalja) in zemljevid.sosedi(mesto):
        poteza = f"{mesto} -> {m2}"
        yield (m2, razdalja, poteza)


class PotDoBukareste:
    """Problem iskanja poti do Bukarešte."""

    def __init__(self, zemljevid, zacetno_mesto, ime_csv=MATERIALI / "romania-bucharest-h.csv"):
        self.zemljevid = zemljevid
        self.zacetno_mesto = zacetno_mesto
        self.cilj = "Bucharest"

        self.h_vrednosti = {}
        with open(ime_csv) as d:
            for v in d:
                m, h = v.split(",")
                self.h_vrednosti[m] = int(h)

    def __repr__(self):
        return f"{type(self).__name__}({self.zemljevid}, {self.zacetno_mesto!r})"

    def zacetno(self):
        return self.zacetno_mesto

    def koncno(self, s):
        return s == self.cilj

    def razveji(self, s):
        return sosedi_generator(self.zemljevid, s)

